def gaussian_kernel(sigma, size=None):
    if size is None:
        size = int(np.ceil(sigma*2.))
        if size % 2 == 0:
            size += 1
    x = np.linspace(-size/2., size/2., size)
    kernel = 1/(np.sqrt(2*np.pi))*np.exp(-x**2/(2*sigma**2))/sigma
    return kernel/np.sum(kernel)

