            geom.R[l] * sympy.Matrix(self.rbtdef.l[l])) * self.Jo[l])

    self.Jc = list(range(self.rbtdef.dof))
    for l in range(self.rbtdef.dof):
        self.Jc[l] = self.Jcp[l].col_join(self.Jco[l])

